pub(crate) fn deobfuscate_odttf(bytes: &[u8], font_key: &str) -> Vec<u8> {
    let mut data = bytes.to_vec();
    let plain_sfnt = [
        &[0x00, 0x01, 0x00, 0x00][..],
        b"OTTO",
        b"true",
        b"typ1",
        b"ttcf",
    ]
    .iter()
    .any(|tag| data.starts_with(tag));
    if !plain_sfnt && let Some(key) = parse_font_key(font_key) {
